from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const initial=','let state=','const esc=','const icons=','const icon=','const t=','const btn=','const notice=','const categoryDefs=','const catName=','const heading=','function review(','function save(')))
line=next(x for x in src if x.startswith('function openModal('));start=line.index("if(type==='research')");end=line.index("else if(type==='permissions')",start);research=line[start:end]
script=defs+'''\nconst compact=innerWidth<=1100;const cases=[];function templates(){const holder=document.createElement('div');holder.innerHTML=review();let list=[...holder.querySelectorAll('.summary-item')].map(x=>x.outerHTML);state.selected.add('trial');holder.innerHTML=review();list.push(holder.querySelectorAll('.summary-item')[5].outerHTML);state.selected.clear();holder.innerHTML=review();list.push(holder.querySelectorAll('.summary-item')[2].outerHTML);state.selected=new Set(categoryDefs.map(x=>x.key));holder.innerHTML=review();list.push(holder.querySelectorAll('.summary-item')[4].outerHTML);holder.innerHTML=save();list.push(...[...holder.querySelectorAll('.summary-item')].map(x=>x.outerHTML));const type='research';let title='',body='';'''+research+''';holder.innerHTML=body;list.push(...[...holder.querySelectorAll('.summary-item')].map(x=>x.outerHTML));state.source.db='migration_sample_with_a_long_database_name';state.target.db='migration_sample_with_a_long_database_name';holder.innerHTML=review();list.push(holder.querySelectorAll('.summary-item')[1].outerHTML);return list}
for(const language of ['ko','en']){lang=language;state=initial();for(const [variant,html] of templates().entries())for(const width of [602,850,1006])for(const last of [false,true]){const f=document.createElement('div');f.className='fixture';f.style.width=width+'px';f.innerHTML=html+(last?'':'<span hidden></span>');const e=f.firstChild;e.dataset.id=`${compact?'compact':'wide'}-${language}-${variant}-${width}-${last}`;const value=e.children[1];let lines=[];if(value.classList.contains('mono'))lines=[value.firstChild?.textContent??''];else{let line='';for(const node of value.childNodes){if(node.nodeName==='BR'){lines.push(line);line=''}else line+=node.textContent}lines.push(line)}cases.push({id:e.dataset.id,width,compact,last,label:e.firstChild.textContent,lines,strong:value.tagName==='STRONG',mono:value.classList.contains('mono'),suffix:value.querySelector('small')?.textContent??''});document.getElementById('fixtures').append(f)}}
function read(){return [...document.querySelectorAll('.summary-item')].map(e=>{const r=e.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}};return{id:e.dataset.id,width:r.width,height:r.height,label:box(e.children[0]),value:box(e.children[1]),labelText:e.children[0].textContent,valueText:e.children[1].textContent,borderBottom:getComputedStyle(e).borderBottomWidth,labelColor:getComputedStyle(e.children[0]).color,valueColor:getComputedStyle(e.children[1]).color}})}'''
(o/'summaryitem-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
(o/'summaryitem-inner.html').write_text('<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="summaryitem-original.css"><style>.fixture{position:absolute;left:30px;top:100px}.fixture:not(:first-child){visibility:hidden}</style><div id="fixtures"></div><script>'+script+'</script>')
outer='''<!doctype html><meta charset="utf-8"><title>SummaryItem · original isolation</title><button id="summaryitem-record">Record SummaryItem</button><iframe width="1000" height="700" src="summaryitem-inner.html"></iframe><iframe width="1400" height="700" src="summaryitem-inner.html" style="position:absolute;left:0;top:0;visibility:hidden"></iframe><script>document.getElementById('summaryitem-record').onclick=async()=>{const frames=[...document.querySelectorAll('iframe')];for(const f of frames)await f.contentDocument.fonts.ready;const rows=frames.flatMap(f=>f.contentWindow.read()),cases=frames.flatMap(f=>f.contentWindow.cases);const res=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows,cases})});if(!res.ok)throw Error('Record failed');document.getElementById('summaryitem-record').textContent='SummaryItem recorded'}</script>'''
